"""Grader: guide_en.md must be an English guide that keeps the structure of guide_es.md."""
import json
import re
import sys
from pathlib import Path

src = Path("guide_es.md").read_text(encoding="utf-8")
out_path = Path("guide_en.md")
if not out_path.is_file():
    sys.exit("guide_en.md does not exist")
out = out_path.read_text(encoding="utf-8")
glossary = json.loads(Path("glossary.json").read_text(encoding="utf-8"))


def headings(t):
    t = re.sub(r"```.*?```", "", t, flags=re.S)
    return [len(m.group(1)) for m in re.finditer(r"^(#{1,6})\s+\S", t, re.M)]


def links(t):
    return re.findall(r"\[[^\]]+\]\(([^)\s]+)\)", t)


def blocks(t):
    return re.findall(r"```.*?```", t, flags=re.S)


def code_spans(t):
    return re.findall(r"`[^`\n]+`", re.sub(r"```.*?```", "", t, flags=re.S))


def prose(t):
    t = re.sub(r"```.*?```", " ", t, flags=re.S)
    t = re.sub(r"`[^`\n]+`", " ", t)
    return re.sub(r"\]\([^)]*\)", "]", t)


if headings(out) != headings(src):
    sys.exit(f"heading levels differ: {headings(out)} vs {headings(src)}")
if links(out) != links(src):
    sys.exit(f"links differ: {links(out)} vs {links(src)}")
if blocks(out) != blocks(src):
    sys.exit("the code block was changed")
if sorted(code_spans(out)) != sorted(code_spans(src)):
    sys.exit("inline code was changed or translated")
words = len(out.split())
if not 330 <= words <= 480:
    sys.exit(f"{words} words; a faithful translation is about 330 to 480")
text = prose(out).lower()
spanish = re.findall(r"\b(?:el|la|los|las|del|que|para|con|una|por|sus|es|más|antes|cada)\b", text)
if len(spanish) > 3:
    sys.exit(f"still Spanish: {sorted(set(spanish))}")
if re.search(r"[¿¡]", text):
    sys.exit("Spanish punctuation left in")
src_l = prose(src).lower()
for es, en in glossary.items():
    w = es.split()
    pat = r"\b" + " ".join([re.escape(w[0]) + "s?"] + [re.escape(x) for x in w[1:]])
    need = max(1, len(re.findall(pat, src_l)) - 1)
    have = text.count(en)
    if have < need:
        sys.exit(f"glossary term '{en}' used {have} times, needed at least {need}")
for bad in ("safety copy", "safety copies", "bookstore", "directory", "directories", "label", "backups copy"):
    if bad in text:
        sys.exit(f"avoid '{bad}'; use the glossary term")
for es in glossary:
    if es in text:
        sys.exit(f"untranslated glossary term: {es}")
print("guide ok")
